//! `espforge`: the command-line face of [`espforge_core`].
//!
//! The binary owns the flags, the terminal and the exit codes; everything
//! between an ESPF file and generated bytes lives in the library. Exit codes:
//! 0 success, 1 the user's input is at fault (already explained), 2 an
//! internal or IO failure.

mod commands;

use std::process::ExitCode;

use clap::{CommandFactory, Parser, Subcommand};

#[derive(Parser)]
#[command(name = "espforge", version, about = "ESPF runtime pipeline tool")]
struct Cli {
    #[command(subcommand)]
    command: Option<Commands>,
}

#[derive(Subcommand)]
enum Commands {
    /// Generate the firmware project only (no cargo).
    ///
    /// Flags override the file; a `note:` says when one changes something.
    #[command(
        name = "gen",
        after_help = "Examples:\n  espforge gen\n  espforge gen hello.espf --chip esp32s3 --option alloc=false\n  espforge gen --example 01.Basics/helloworld --out /tmp/hw"
    )]
    Gen(commands::generate::GenArgs),
}

fn main() -> ExitCode {
    match Cli::parse().command {
        Some(Commands::Gen(args)) => commands::generate::run(args),
        // No subcommand given: show help instead of erroring.
        None => {
            Cli::command()
                .print_help()
                .expect("rendering help should not fail");
            ExitCode::SUCCESS
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_only_subcommand_is_gen() {
        let cmd = Cli::command();
        let names: Vec<&str> = cmd.get_subcommands().map(|c| c.get_name()).collect();
        assert_eq!(names, ["gen"]);
    }

    #[test]
    fn gen_accepts_a_file_or_an_example_but_not_both() {
        assert!(Cli::try_parse_from(["espforge", "gen", "hello.espf"]).is_ok());
        assert!(
            Cli::try_parse_from(["espforge", "gen", "--example", "01.Basics/helloworld"]).is_ok()
        );
        assert!(
            Cli::try_parse_from([
                "espforge",
                "gen",
                "hello.espf",
                "--example",
                "01.Basics/helloworld",
            ])
            .is_err()
        );
    }
}
